package com.bank.sre;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Drills from the symptom to the systemic root cause by repeatedly asking "why".
public class FiveWhys {
    private static final Logger log = Logger.getLogger(FiveWhys.class.getName());
    private final List<String> chain = new ArrayList<>();

    public FiveWhys symptom(String s) { chain.add("SYMPTOM: " + s); return this; }
    public FiveWhys why(String answer) { chain.add("WHY -> " + answer); return this; }

    // The last answer is treated as the systemic root cause.
    public String rootCause() { return chain.get(chain.size() - 1).replace("WHY -> ", ""); }

    public void print() {
        for (String step : chain) log.info("  " + step);
        log.warning("ROOT CAUSE (systemic, not a person): " + rootCause());
    }
}
