package com.bank.sre;

import java.time.Duration;
import java.time.LocalTime;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Assembles the blameless post-mortem from timeline, root cause, and action items.
public class Postmortem {
    private static final Logger log = Logger.getLogger(Postmortem.class.getName());

    private final String title;
    private final List<TimelineEvent> timeline = new ArrayList<>();
    private FiveWhys analysis;
    private final List<ActionItem> actions = new ArrayList<>();
    private long affectedTransfers;

    public Postmortem(String title) { this.title = title; }

    public void addEvent(TimelineEvent e) { timeline.add(e); }
    public void setAnalysis(FiveWhys a) { this.analysis = a; }
    public void addAction(ActionItem a) { actions.add(a); }
    public void setAffectedTransfers(long n) { this.affectedTransfers = n; }

    // Duration from first symptom to recovery, from the factual timeline.
    public long outageMinutes() {
        LocalTime start = timeline.get(0).getAt();
        LocalTime end = timeline.get(timeline.size() - 1).getAt();
        return Duration.between(start, end).toMinutes();
    }

    public void publish() {
        log.info("===== BLAMELESS POST-MORTEM: " + title + " =====");
        log.info("IMPACT: " + affectedTransfers + " failed transfers over "
                + outageMinutes() + " minutes");
        log.info("TIMELINE:");
        for (TimelineEvent e : timeline)
            log.info("  " + e.getAt() + "  " + e.getDescription());
        log.info("ROOT CAUSE ANALYSIS (Five Whys):");
        analysis.print();
        log.info("ACTION ITEMS (owned + tracked):");
        for (ActionItem a : actions) log.info("  " + a);
        log.info("Reminder: blameless — we fix the SYSTEM, not punish a person.");
    }
}
