package com.bank.sre;

import java.time.LocalTime;
import java.util.logging.*;

// Runnable demo: assemble and publish the blameless post-mortem for the outage.
public class PostmortemDemo {
    private static final Logger log = Logger.getLogger(PostmortemDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Postmortem pm = new Postmortem("Transfer Service Outage 2026-10-29");
        pm.setAffectedTransfers(12400);

        // Factual timeline from evidence (deploy logs, alerts, chat).
        pm.addEvent(new TimelineEvent(LocalTime.of(14, 2), "config deploy pool.maxSize=0 shipped"));
        pm.addEvent(new TimelineEvent(LocalTime.of(14, 2), "transfers begin failing (SAV2001/CUR3001)"));
        pm.addEvent(new TimelineEvent(LocalTime.of(14, 10), "alert fired (8 min late)"));
        pm.addEvent(new TimelineEvent(LocalTime.of(14, 28), "root cause identified: bad config"));
        pm.addEvent(new TimelineEvent(LocalTime.of(14, 32), "rollback complete, service recovered"));

        // Five Whys: trigger -> systemic root cause.
        FiveWhys analysis = new FiveWhys()
            .symptom("all transfers failed")
            .why("DB connection pool had maxSize=0, so no connections")
            .why("a bad config value pool.maxSize=0 was deployed")
            .why("the deploy pipeline did not validate config values")
            .why("config validation was never added to the pipeline")
            .why("no requirement/guardrail for config schema checks (SYSTEM gap)");
        pm.setAnalysis(analysis);

        // Owned, tracked action items across all three categories.
        pm.addAction(new ActionItem(ActionItem.Category.PREVENT,
            "add config schema validation to deploy pipeline", "@platform", "2026-11-05"));
        pm.addAction(new ActionItem(ActionItem.Category.DETECT,
            "staging config parity check", "@sre", "2026-11-12"));
        pm.addAction(new ActionItem(ActionItem.Category.DETECT,
            "alert on transfer error-rate within 1 minute", "@sre", "2026-11-08"));
        pm.addAction(new ActionItem(ActionItem.Category.MITIGATE,
            "canary config rollout to 1% before full deploy", "@platform", "2026-11-20"));

        pm.publish();
    }
}
